package com.gymmind.knowledge.infrastructure.search;
import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.*;
class TenantIndexIsolationTest { @Test void keywordAndVectorSearchFilterTenant(){var k=new InMemoryKeywordIndex();var v=new InMemoryVectorIndex();var vector=new float[1024];vector[0]=1;var x=new IndexedChunk("c1",7L,"hello",vector);k.upsert(x);v.upsert(x);assertThat(k.search("hello",7L)).hasSize(1);assertThat(k.search("hello",8L)).isEmpty();assertThat(v.search(vector,8L)).isEmpty();}
 @Test void deletingDocumentKeepsOtherDocumentsAndTenants(){var k=new InMemoryKeywordIndex();var v=new InMemoryVectorIndex();var vector=new float[1024];vector[0]=1;for(var c:java.util.List.of(new IndexedChunk("a",7L,3L,null,"alpha",vector),new IndexedChunk("b",7L,4L,null,"beta",vector),new IndexedChunk("c",8L,3L,null,"gamma",vector))){k.upsert(c);v.upsert(c);}k.deleteDocument(7L,3L);v.deleteDocument(7L,3L);assertThat(k.search("",7L)).extracting(IndexedChunk::id).containsExactly("b");assertThat(v.search(vector,7L)).extracting(IndexedChunk::id).containsExactly("b");assertThat(k.search("",8L)).extracting(IndexedChunk::id).containsExactly("c");assertThat(v.search(vector,8L)).extracting(IndexedChunk::id).containsExactly("c");}
 @Test void keywordSearchRanksChineseQueryTermsInsteadOfRequiringWholeSentence(){var k=new InMemoryKeywordIndex();k.upsert(new IndexedChunk("weak",7L,"动作数量安排",new float[1024]));k.upsert(new IndexedChunk("relevant",7L,"新手力量训练先热身",new float[1024]));assertThat(k.search("新手做力量训练要注意什么？",7L)).extracting(IndexedChunk::id).containsExactly("relevant");}
 @Test void searchAcrossTenantAndPlatformScopes(){KeywordIndexPort k=new InMemoryKeywordIndex();var platform=new IndexedChunk("platform",0L,"default",new float[1024]);var tenant=new IndexedChunk("tenant",7L,"custom",new float[1024]);k.upsert(platform);k.upsert(tenant);assertThat(k.search("",java.util.List.of(7L,0L),null)).extracting(IndexedChunk::id).containsExactlyInAnyOrder("platform","tenant");}
 @Test void privateChunksAreVisibleOnlyToTheirOwner(){var k=new InMemoryKeywordIndex();var v=new InMemoryVectorIndex();var vector=new float[1024];vector[0]=1;var x=new IndexedChunk("private",7L,11L,"secret",vector);k.upsert(x);v.upsert(x);assertThat(k.search("secret",7L,11L)).hasSize(1);assertThat(k.search("secret",7L,12L)).isEmpty();assertThat(v.search(vector,7L,12L)).isEmpty();}
}
